fn main() &#123;    // 整数类型示例    let a: i32 = -42;           // 有符号 32 位整数（默认类型）    let b: u8 = 255;            // 无符号 8 位整数（0~255）    let c: usize = 100;         // 指针大小的无符号整数    // 字面量可加分隔符提高可读性    let d = 1_000_000;          // 等同于 1000000    // 不同进制表示    let hex = 0xff;             // 十六进制 255    let oct = 0o77;             // 八进制 63    let bin = 0b1111_0000;      // 二进制 240    let byte = b&#x27;A&#x27;;            // 字节字面量 65    println!(&quot;a=&#123;&#125;, b=&#123;&#125;, c=&#123;&#125;, d=&#123;&#125;&quot;, a, b, c, d);    println!(&quot;hex=&#123;&#125;, oct=&#123;&#125;, bin=&#123;&#125;, byte=&#123;&#125;&quot;, hex, oct, bin, byte);&#125;
浮点数类型
fn main() &#123;    let x: f32 = 3.14;          // 单精度浮点数    let y: f64 = 2.71828;       // 双精度浮点数（默认类型）    let z = 1.0;                // 默认 f64    // 基本数学运算    println!(&quot;加: &#123;&#125;&quot;, x + 1.0);    // 输出 4.14    println!(&quot;减: &#123;&#125;&quot;, y - 1.0);    // 输出 1.71828    println!(&quot;乘: &#123;&#125;&quot;, 2.5 * 2.0);  // 输出 5    println!(&quot;除: &#123;&#125;&quot;, 5.0 / 2.0);  // 输出 2.5    println!(&quot;取余: &#123;&#125;&quot;, 7.0 % 3.0); // 输出 1&#125;
布尔类型
fn main() &#123;    let t: bool = true;    let f: bool = false;        // 显式类型标注    let is_ok = true;           // 类型推断    // 布尔值常用于条件判断    if is_ok &#123;        println!(&quot;一切正常！&quot;);    &#125;    println!(&quot;t=&#123;&#125;, f=&#123;&#125;&quot;, t, f);&#125;
字符类型
fn main() &#123;    // char 类型占 4 字节，表示一个 Unicode 标量值    let c: char = &#x27;A&#x27;;    let emoji: char = &#x27;🦀&#x27;;     // 支持 emoji    let zh: char = &#x27;中&#x27;;        // 支持中文    println!(&quot;c=&#123;&#125;, emoji=&#123;&#125;, zh=&#123;&#125;&quot;, c, emoji, zh);    println!(&quot;char 占用 &#123;&#125; 字节&quot;, std::mem::size_of::&lt;char&gt;()); // 输出 4&#125;
2. 复合类型（Compound Types）
元组（Tuple）
fn main() &#123;    // 元组可以包含不同类型，长度固定    let tup: (i32, f64, char) = (500, 6.4, &#x27;R&#x27;);    // 模式匹配解构    let (x, y, z) = tup;    println!(&quot;x=&#123;&#125;, y=&#123;&#125;, z=&#123;&#125;&quot;, x, y, z); // 输出 x=500, y=6.4, z=R    // 使用点索引访问（从 0 开始）    println!(&quot;第一个: &#123;&#125;&quot;, tup.0);  // 输出 500    println!(&quot;第二个: &#123;&#125;&quot;, tup.1);  // 输出 6.4    println!(&quot;第三个: &#123;&#125;&quot;, tup.2);  // 输出 R    // 空元组 () 称为单元类型，用于不返回值的表达式    let empty: () = ();&#125;
数组（Array）
fn main() &#123;    // 数组长度固定，所有元素类型相同，分配在栈上    let arr: [i32; 5] = [1, 2, 3, 4, 5];    // 简写：创建 3 个值为 0 的数组    let zeros = [0; 3];  // [0, 0, 0]    // 索引访问（从 0 开始）    println!(&quot;第一个: &#123;&#125;&quot;, arr[0]);     // 输出 1    println!(&quot;数组长度: &#123;&#125;&quot;, arr.len()); // 输出 5    // 数组越界会在运行时 panic（程序崩溃）    // let x = arr[10]; // ❌ index out of bounds    // 遍历数组    for element in arr.iter() &#123;        println!(&quot;元素: &#123;&#125;&quot;, element);    &#125;    // 带索引遍历    for (i, val) in arr.iter().enumerate() &#123;        println!(&quot;arr[&#123;&#125;] = &#123;&#125;&quot;, i, val);    &#125;&#125;
函数与作用域
Rust 使用 fn 关键字定义函数，函数名遵循蛇形命名法（snake_case）。main 函数是程序的入口点。

1. 函数定义与调用
fn main() &#123;    // 调用自定义函数    greet();    let result = add(10, 20);    println!(&quot;10 + 20 = &#123;&#125;&quot;, result);&#125;// 无参无返回值函数fn greet() &#123;    println!(&quot;Hello, Rust!&quot;);&#125;// 带参数和返回值的函数（-&gt; 标注返回类型）fn add(a: i32, b: i32) -&gt; i32 &#123;    // 最后一行不带分号即为返回值（表达式返回）    a + b  // 返回 a + b&#125;
2. 语句与表达式
fn main() &#123;    // 语句：执行操作但不返回值，以分号结尾    let x = 5;  // let 语句    // 表达式：计算并返回值，不以分号结尾    let y = &#123;        let a = 3;        a + 1  // 表达式，返回 4    &#125;;    println!(&quot;y = &#123;&#125;&quot;, y);  // 输出 y = 4    // 函数体内最后的表达式即为返回值    let z = double(5);    println!(&quot;double(5) = &#123;&#125;&quot;, z); // 输出 10&#125;fn double(n: i32) -&gt; i32 &#123;    n * 2  // 表达式返回，不能加分号&#125;
3. 作用域
fn main() &#123;    let outer = 100;  // outer 在整个 main 中有效    &#123;        // 进入一个新的作用域        let inner = 200;         // inner 仅在此作用域有效        println!(&quot;内部: outer=&#123;&#125;, inner=&#123;&#125;&quot;, outer, inner);        // inner 在此处之后被释放（drop）    &#125;    println!(&quot;外部: outer=&#123;&#125;&quot;, outer);    // println!(&quot;&#123;&#125;&quot;, inner); // ❌ 编译错误！inner 已超出作用域&#125;
流程控制
Rust 通过 if、loop、while、for 来控制代码的执行流程。

1. if 表达式
fn main() &#123;    let number = 7;    // 基本 if-else    if number &lt; 5 &#123;        println!(&quot;数字小于 5&quot;);    &#125; else if number == 5 &#123;        println!(&quot;数字等于 5&quot;);    &#125; else &#123;        println!(&quot;数字大于 5&quot;); // 走这里    &#125;    // if 是表达式，可以用于赋值（各分支必须返回相同类型）    let result = if number % 2 == 0 &#123; &quot;偶数&quot; &#125; else &#123; &quot;奇数&quot; &#125;;    println!(&quot;&#123;&#125; 是&#123;&#125;&quot;, number, result); // 输出 7 是奇数    // 条件必须是 bool 类型，不支持隐式转换    // if number &#123; &#125; // ❌ number 不是 bool&#125;
2. loop 循环
fn main() &#123;    let mut count = 0;    // loop 无限循环，使用 break 退出    loop &#123;        count += 1;        println!(&quot;count = &#123;&#125;&quot;, count);        if count &gt;= 3 &#123;            break; // 退出循环        &#125;    &#125;    // loop 可以返回值    let result = loop &#123;        count += 1;        if count == 10 &#123;            break count * 2; // break 后跟返回值        &#125;    &#125;;    println!(&quot;result = &#123;&#125;&quot;, result); // 输出 result = 20&#125;
3. while 循环
fn main() &#123;    let mut n = 3;    // 条件循环    while n &gt; 0 &#123;        println!(&quot;倒计时: &#123;&#125;&quot;, n);        n -= 1;    &#125;    println!(&quot;发射！🚀&quot;);    // 遍历数组（用 while 不如用 for 方便）    let arr = [10, 20, 30, 40, 50];    let mut index = 0;    while index &lt; arr.len() &#123;        println!(&quot;arr[&#123;&#125;] = &#123;&#125;&quot;, index, arr[index]);        index += 1;    &#125;&#125;
4. for 循环
fn main() &#123;    let arr = [10, 20, 30, 40, 50];    // for in 遍历集合（推荐方式，安全高效）    for element in arr.iter() &#123;        println!(&quot;元素: &#123;&#125;&quot;, element);    &#125;    // 遍历范围（左闭右开）    for i in 0..5 &#123;        println!(&quot;i = &#123;&#125;&quot;, i); // 输出 0, 1, 2, 3, 4    &#125;    // 遍历范围（左闭右闭）    for i in 1..=3 &#123;        println!(&quot;i = &#123;&#125;&quot;, i); // 输出 1, 2, 3    &#125;    // 反向遍历    for i in (1..=5).rev() &#123;        println!(&quot;倒序: &#123;&#125;&quot;, i); // 输出 5, 4, 3, 2, 1    &#125;&#125;
所有权与借用（Ownership and Borrowing）
所有权是 Rust 最独特的特性，它让 Rust 无需垃圾回收器就能保证内存安全。所有权规则：每个值有且只有一个所有者；值在所有者离开作用域时被释放。

1. 所有权规则
fn main() &#123;    // 规则一：每个值都有一个所有者    let s1 = String::from(&quot;hello&quot;);    println!(&quot;s1 = &#123;&#125;&quot;, s1);    // s1 是 &quot;hello&quot; 这个 String 的所有者    // 规则二：同一时刻只能有一个所有者    let s2 = s1;  // s1 的所有权移动（move）给了 s2    // println!(&quot;&#123;&#125;&quot;, s1);  // ❌ s1 已失效！    println!(&quot;s2 = &#123;&#125;&quot;, s2);    // 规则三：所有者离开作用域时，值被释放    &#123;        let s3 = String::from(&quot;temp&quot;);        println!(&quot;内部: &#123;&#125;&quot;, s3);        // s3 在此被 drop，内存释放    &#125;    // println!(&quot;&#123;&#125;&quot;, s3); // ❌ s3 已超出作用域&#125;
2. 所有权与函数
fn main() &#123;    let s = String::from(&quot;hello&quot;);    // 将 s 传入函数，所有权随之移动    takes_ownership(s);    // println!(&quot;&#123;&#125;&quot;, s); // ❌ s 的所有权已移入函数    // 基本类型（实现了 Copy trait）会自动复制    let x = 5;    makes_copy(x);           // x 被复制，所有权不变    println!(&quot;x 仍然可用: &#123;&#125;&quot;, x); // ✅    // 函数返回时也可以转移所有权    let s1 = gives_ownership();         // 函数返回值所有权移给 s1    let s2 = String::from(&quot;world&quot;);    let s3 = takes_and_gives_back(s2);  // s2 移入，s3 获得返回值的所有权    println!(&quot;s1=&#123;&#125;, s3=&#123;&#125;&quot;, s1, s3);&#125;fn takes_ownership(s: String) &#123;    println!(&quot;获取了所有权: &#123;&#125;&quot;, s);    // s 离开作用域，内存释放&#125;fn makes_copy(n: i32) &#123;    println!(&quot;复制了: &#123;&#125;&quot;, n);&#125;fn gives_ownership() -&gt; String &#123;    let s = String::from(&quot;from function&quot;);    s // 返回 s，所有权移出&#125;fn takes_and_gives_back(s: String) -&gt; String &#123;    s // 返回 s，所有权移出&#125;
3. 借用（Borrowing）
fn main() &#123;    let s = String::from(&quot;hello&quot;);    // 不可变借用：使用 &amp; 创建引用    let len = calculate_length(&amp;s); // &amp;s 创建一个指向 s 的引用    // 借用不会转移所有权    println!(&quot;&#x27;&#123;&#125;&#x27; 的长度是 &#123;&#125;&quot;, s, len); // ✅ s 仍然可用    // 可变借用    let mut s2 = String::from(&quot;hello&quot;);    change(&amp;mut s2);              // &amp;mut 创建可变引用    println!(&quot;修改后: &#123;&#125;&quot;, s2);   // 输出 hello, world!    // 借用规则：    // 1. 同一时刻，要么多个不可变引用，要么一个可变引用    // 2. 引用必须始终有效（不会悬垂）    let r1 = &amp;s2;       // ✅ 不可变引用    let r2 = &amp;s2;       // ✅ 可以有多个不可变引用    // let r3 = &amp;mut s2;  // ❌ 已有不可变引用时不能创建可变引用    println!(&quot;r1=&#123;&#125;, r2=&#123;&#125;&quot;, r1, r2);    // r1, r2 在此之后不再使用    let r3 = &amp;mut s2;   // ✅ 现在可以了（r1, r2 已不再使用）    r3.push_str(&quot;!!!&quot;);    println!(&quot;r3=&#123;&#125;&quot;, r3);    // 这个作用域称为 NLL（Non-Lexical Lifetimes）&#125;fn calculate_length(s: &amp;String) -&gt; usize &#123; // &amp;String 表示借用    s.len()    // s 是引用，离开作用域时不会释放所指数据&#125;fn change(s: &amp;mut String) &#123;    s.push_str(&quot;, world!&quot;); // 通过可变引用修改原数据&#125;
引用与切片（References and Slices）
切片（Slice）是对集合中连续元素的引用，不拥有数据。最常见的切片类型是字符串切片 &amp;str 和数组切片 &amp;[T]。

1. 字符串切片
fn main() &#123;    let s = String::from(&quot;hello world&quot;);    // 字符串切片 [起始..结束) ，左闭右开    let hello = &amp;s[0..5];   // 取 0 到 4 索引的字符    let world = &amp;s[6..11];  // 取 6 到 10 索引的字符    println!(&quot;&#123;&#125;, &#123;&#125;!&quot;, hello, world);  // 输出 hello, world!    // 简写    let h = &amp;s[..5];        // 从开头到索引 5（不含）    let w = &amp;s[6..];        // 从索引 6 到结尾    let all = &amp;s[..];       // 整个字符串切片    println!(&quot;h=&#123;&#125;, w=&#123;&#125;, all=&#123;&#125;&quot;, h, w, all);    // 推荐函数参数使用 &amp;str 而非 &amp;String    let first = first_word(&amp;s);    println!(&quot;第一个单词: &#123;&#125;&quot;, first);  // 输出 hello    // 字符串字面量本身就是切片    let literal = &quot;hello world&quot;; // literal 的类型是 &amp;str    let first2 = first_word(literal);    println!(&quot;第一个单词: &#123;&#125;&quot;, first2);    // 注意：切片引用与原始数据的关联    // let mut s2 = String::from(&quot;hello&quot;);    // let slice = &amp;s2[..];  // 不可变借用    // s2.clear();           // ❌ 可变借用与不可变借用冲突！    // println!(&quot;&#123;&#125;&quot;, slice);&#125;// 使用 &amp;str 作为参数，可同时接受 &amp;String 和 &amp;strfn first_word(s: &amp;str) -&gt; &amp;str &#123;    let bytes = s.as_bytes();    for (i, &amp;item) in bytes.iter().enumerate() &#123;        if item == b&#x27; &#x27; &#123;            return &amp;s[..i]; // 返回第一个空格之前的切片        &#125;    &#125;    &amp;s[..] // 没有空格，返回整个字符串&#125;
2. 数组切片
fn main() &#123;    let arr = [1, 2, 3, 4, 5];    // 数组切片类型是 &amp;[i32]    let slice: &amp;[i32] = &amp;arr[1..4];  // 取索引 1, 2, 3    println!(&quot;切片: &#123;:?&#125;&quot;, slice);    // 输出 [2, 3, 4]    // 切片和原数组共享数据    println!(&quot;第一个元素: &#123;&#125;&quot;, slice[0]); // 输出 2    println!(&quot;切片长度: &#123;&#125;&quot;, slice.len()); // 输出 3    // 判断切片是否为空    let empty: &amp;[i32] = &amp;[];    println!(&quot;empty.is_empty() = &#123;&#125;&quot;, empty.is_empty()); // 输出 true    // 遍历切片    for val in slice.iter() &#123;        println!(&quot;元素: &#123;&#125;&quot;, val);    &#125;&#125;
结构体（Struct）和方法
结构体是一种自定义数据类型，用于将多个相关的值组合成一个有意义的整体。可以为其定义方法，方法定义在 impl 块中。

1. 定义与实例化结构体
// 定义结构体struct User &#123;    username: String,    email: String,    active: bool,&#125;fn main() &#123;    // 创建实例（字段必须全部初始化）    let user1 = User &#123;        email: String::from(&quot;alice@example.com&quot;),        username: String::from(&quot;alice&quot;),        active: true,    &#125;;    println!(&quot;用户名: &#123;&#125;, 邮箱: &#123;&#125;&quot;, user1.username, user1.email);    // 如果实例声明为 mut，所有字段都可变    let mut user2 = User &#123;        email: String::from(&quot;bob@example.com&quot;),        username: String::from(&quot;bob&quot;),        active: false,    &#125;;    user2.active = true;  // ✅ 修改字段    println!(&quot;&#123;&#125; 激活状态: &#123;&#125;&quot;, user2.username, user2.active);    // 结构体更新语法（类似 JS 展开运算符）    let user3 = User &#123;        email: String::from(&quot;charlie@example.com&quot;),        ..user2  // 其余字段从 user2 获取（注意：user2.username 的所有权被移走了）    &#125;;    println!(&quot;新用户: &#123;&#125;, &#123;&#125;&quot;, user3.username, user3.email);    // println!(&quot;&#123;&#125;&quot;, user2.username); // ❌ user2.username 已失效&#125;
2. 元组结构体和单元结构体
// 元组结构体：有结构体名但没有字段名struct Color(i32, i32, i32);struct Point(f64, f64);// 单元结构体：没有任何字段struct AlwaysEqual;fn main() &#123;    let black = Color(0, 0, 0);    let origin = Point(0.0, 0.0);    // 通过索引访问元组结构体字段    println!(&quot;R: &#123;&#125;, G: &#123;&#125;, B: &#123;&#125;&quot;, black.0, black.1, black.2);    println!(&quot;x: &#123;&#125;, y: &#123;&#125;&quot;, origin.0, origin.1);    let _subject = AlwaysEqual; // 单元结构体实例    // 单元结构体常用于实现 trait 但不需要存储数据&#125;
3. 方法定义（impl 块）
struct Rectangle &#123;    width: u32,    height: u32,&#125;// impl 块中定义方法impl Rectangle &#123;    // 关联函数（没有 self 参数）—— 相当于静态方法    fn square(size: u32) -&gt; Rectangle &#123;        Rectangle &#123;            width: size,            height: size,        &#125;    &#125;    // 方法：第一个参数是 &amp;self（不可变借用）    fn area(&amp;self) -&gt; u32 &#123;        self.width * self.height    &#125;    // &amp;mut self：可变借用    fn double_size(&amp;mut self) &#123;        self.width *= 2;        self.height *= 2;    &#125;    // self：获取所有权（较少使用）    fn destroy(self) -&gt; (u32, u32) &#123;        (self.width, self.height)    &#125;    // 可以调用其他方法    fn can_hold(&amp;self, other: &amp;Rectangle) -&gt; bool &#123;        self.width &gt; other.width &amp;&amp; self.height &gt; other.height    &#125;&#125;fn main() &#123;    let mut rect = Rectangle &#123;        width: 30,        height: 50,    &#125;;    // 调用方法（自动解引用）    println!(&quot;面积: &#123;&#125; 平方像素&quot;, rect.area()); // 输出 1500    // 调用可变借用方法    rect.double_size();    println!(&quot;放大后: &#123;&#125; x &#123;&#125;&quot;, rect.width, rect.height); // 输出 60 x 100    // 调用关联函数：使用 :: 语法    let sq = Rectangle::square(10);    println!(&quot;正方形面积: &#123;&#125;&quot;, sq.area()); // 输出 100    // 比较矩形    let small = Rectangle &#123; width: 5, height: 5 &#125;;    println!(&quot;rect 能容纳 small 吗？&#123;&#125;&quot;, rect.can_hold(&amp;small));&#125;
枚举与模式匹配
枚举（enum）定义了一组可能的取值类型。结合 match 模式匹配，Rust 能安全地处理所有情况，编译器会检查是否覆盖了所有分支。

1. 枚举定义与使用
// 基本枚举#[derive(Debug)] // 自动实现 Debug trait，使枚举可打印enum IpAddrKind &#123;    V4,    V6,&#125;// 带数据的枚举#[derive(Debug)]enum IpAddr &#123;    V4(u8, u8, u8, u8),  // 关联数据    V6(String),&#125;// 枚举也可以定义方法impl IpAddr &#123;    fn describe(&amp;self) -&gt; String &#123;        match self &#123;            IpAddr::V4(a, b, c, d) =&gt; format!(&quot;IPv4: &#123;&#125;.&#123;&#125;.&#123;&#125;.&#123;&#125;&quot;, a, b, c, d),            IpAddr::V6(addr) =&gt; format!(&quot;IPv6: &#123;&#125;&quot;, addr),        &#125;    &#125;&#125;fn main() &#123;    let four = IpAddrKind::V4;    let six = IpAddrKind::V6;    println!(&quot;&#123;:?&#125;, &#123;:?&#125;&quot;, four, six);    let home = IpAddr::V4(127, 0, 0, 1);    let loopback = IpAddr::V6(String::from(&quot;::1&quot;));    println!(&quot;&#123;:?&#125;&quot;, home);    println!(&quot;&#123;&#125;&quot;, home.describe());   // 输出 IPv4: 127.0.0.1    println!(&quot;&#123;&#125;&quot;, loopback.describe()); // 输出 IPv6: ::1&#125;
2. Option 枚举（替代空值）
fn main() &#123;    // Option&lt;T&gt; 是标准库定义的枚举，用于表示可能有值或没有值    // enum Option&lt;T&gt; &#123; Some(T), None &#125;    // Option 和其变体都被自动引入作用域    let some_number = Some(5);       // Option&lt;i32&gt;    let some_string = Some(&quot;hello&quot;); // Option&lt;&amp;str&gt;    let absent: Option&lt;i32&gt; = None;  // 必须标注类型    // 使用 Option 值前需要处理 None 的情况    let x = 5;    let y = Some(10);    // 不能直接运算：x + y // ❌ 类型不匹配 i32 + Option&lt;i32&gt;    let sum = x + y.unwrap_or(0); // 使用 unwrap_or 提供默认值    println!(&quot;sum = &#123;&#125;&quot;, sum);    // 输出 15&#125;
3. match 模式匹配
#[derive(Debug)]enum Coin &#123;    Penny,    Nickel,    Dime,    Quarter,&#125;// 带数据的枚举变体#[derive(Debug)]enum Message &#123;    Quit,    Move &#123; x: i32, y: i32 &#125;,    Write(String),    ChangeColor(i32, i32, i32),&#125;fn main() &#123;    // match 必须覆盖所有可能的分支    let coin = Coin::Dime;    let value = value_in_cents(coin);    println!(&quot;价值: &#123;&#125; 美分&quot;, value);    // 使用 match 处理 Option    let opt_val = Some(3);    let result = plus_one(opt_val);    println!(&quot;&#123;:?&#125;&quot;, result); // 输出 Some(4)    let none_val = plus_one(None);    println!(&quot;&#123;:?&#125;&quot;, none_val); // 输出 None    // 匹配带数据的枚举    let msg = Message::Write(String::from(&quot;hello&quot;));    process_message(msg);    let msg2 = Message::Move &#123; x: 10, y: 20 &#125;;    process_message(msg2);&#125;fn value_in_cents(coin: Coin) -&gt; u8 &#123;    match coin &#123;        Coin::Penny =&gt; &#123;            println!(&quot;幸运便士！&quot;);            1        &#125;        Coin::Nickel =&gt; 5,        Coin::Dime =&gt; 10,        Coin::Quarter =&gt; 25,    &#125;&#125;fn plus_one(x: Option&lt;i32&gt;) -&gt; Option&lt;i32&gt; &#123;    match x &#123;        None =&gt; None,        Some(i) =&gt; Some(i + 1),    &#125;&#125;fn process_message(msg: Message) &#123;    match msg &#123;        Message::Quit =&gt; println!(&quot;退出&quot;),        Message::Move &#123; x, y &#125; =&gt; println!(&quot;移动到 (&#123;&#125;, &#123;&#125;)&quot;, x, y),        Message::Write(text) =&gt; println!(&quot;写入: &#123;&#125;&quot;, text),        Message::ChangeColor(r, g, b) =&gt; println!(&quot;改为颜色 (&#123;&#125;, &#123;&#125;, &#123;&#125;)&quot;, r, g, b),    &#125;&#125;
4. if let 简洁控制流
fn main() &#123;    let config_max = Some(3u8);    // 使用 match（啰嗦但完整）    match config_max &#123;        Some(max) =&gt; println!(&quot;最大值配置为 &#123;&#125;&quot;, max),        _ =&gt; (), // 忽略其他变体    &#125;    // 等价于 if let（简洁，但失去穷尽性检查）    if let Some(max) = config_max &#123;        println!(&quot;最大值配置为 &#123;&#125;&quot;, max);    &#125;    // if let 也可以配合 else    let coin = Some(5);    if let Some(value) = coin &#123;        println!(&quot;硬币价值: &#123;&#125;&quot;, value);    &#125; else &#123;        println!(&quot;没有硬币&quot;);    &#125;&#125;
常见集合类型及常用操作
Rust 标准库提供了几种通用的集合类型：Vec&lt;T&gt;（动态数组）、String（字符串）、HashMap&lt;K,V&gt;（哈希映射）。

1. Vec&lt;T&gt; 动态数组
fn main() &#123;    // 创建向量    let mut v1: Vec&lt;i32&gt; = Vec::new();    let mut v2 = vec![1, 2, 3];  // vec! 宏创建    // 添加元素    v1.push(10);    v1.push(20);    v1.push(30);    // 读取元素    println!(&quot;v1[0] = &#123;&#125;&quot;, v1[0]);        // 索引访问（越界会 panic）    println!(&quot;v1.get(1) = &#123;:?&#125;&quot;, v1.get(1)); // get 返回 Option，安全    println!(&quot;v1.get(100) = &#123;:?&#125;&quot;, v1.get(100)); // 返回 None    // 遍历向量    for val in &amp;v2 &#123;        println!(&quot;元素: &#123;&#125;&quot;, val);    &#125;    // 遍历并修改    for val in &amp;mut v2 &#123;        *val *= 2; // * 解引用    &#125;    println!(&quot;翻倍后: &#123;:?&#125;&quot;, v2); // 输出 [2, 4, 6]    // 常用操作    println!(&quot;长度: &#123;&#125;&quot;, v2.len());         // 输出 3    println!(&quot;是否为空: &#123;&#125;&quot;, v2.is_empty()); // 输出 false    v2.pop();                                // 移除最后一个元素，返回 Option&lt;T&gt;    println!(&quot;pop 后: &#123;:?&#125;&quot;, v2);           // 输出 [2, 4]    // 枚举类型可以在向量中存储不同类型（通过枚举统一类型）    #[derive(Debug)]    enum Cell &#123;        Int(i32),        Text(String),        Float(f64),    &#125;    let row = vec![        Cell::Int(42),        Cell::Text(String::from(&quot;hello&quot;)),        Cell::Float(3.14),    ];    println!(&quot;行数据: &#123;:?&#125;&quot;, row);&#125;
2. String 字符串
fn main() &#123;    // 创建字符串    let mut s1 = String::new();    let mut s2 = String::from(&quot;hello&quot;);    // 从 &amp;str 创建    let s3 = &quot;world&quot;.to_string();          // to_string 方法    // 追加内容    s1.push_str(&quot;rust&quot;);                   // 追加 &amp;str（不获取所有权）    s2.push(&#x27; &#x27;);                          // 追加单个字符    s2.push_str(&quot;world&quot;);    // 拼接    let joined = format!(&quot;&#123;&#125;-&#123;&#125;-&#123;&#125;&quot;, s1, s2, s3); // format! 宏（不获取所有权）    println!(&quot;拼接结果: &#123;&#125;&quot;, joined);    // 使用 + 运算符拼接（会获取第一个字符串的所有权）    let combined = s1 + &quot; &amp; &quot; + &amp;s3;    println!(&quot;combined: &#123;&#125;&quot;, combined);    // println!(&quot;&#123;&#125;&quot;, s1); // ❌ s1 已被移动    // 遍历字符    for c in &quot;你好&quot;.chars() &#123;        println!(&quot;字符: &#123;&#125;&quot;, c);    &#125;    // 遍历字节    for b in &quot;ABC&quot;.bytes() &#123;        println!(&quot;字节: &#123;&#125;&quot;, b);    &#125;    // 索引与切片（需注意 UTF-8 边界）    let hello = String::from(&quot;你好世界&quot;);    let slice = &amp;hello[0..3]; // 一个中文字符占 3 字节（UTF-8）    println!(&quot;切片: &#123;&#125;&quot;, slice); // 输出 你    // 常用方法    let s = String::from(&quot;hello world&quot;);    println!(&quot;长度(字节): &#123;&#125;&quot;, s.len());             // 输出 11    println!(&quot;是否为空: &#123;&#125;&quot;, s.is_empty());          // 输出 false    println!(&quot;包含&#x27;world&#x27;: &#123;&#125;&quot;, s.contains(&quot;world&quot;)); // 输出 true    println!(&quot;替换: &#123;&#125;&quot;, s.replace(&quot;world&quot;, &quot;rust&quot;)); // 输出 hello rust    let words: Vec&lt;&amp;str&gt; = s.split(&#x27; &#x27;).collect();   // 分割    println!(&quot;拆分结果: &#123;:?&#125;&quot;, words);                // 输出 [&quot;hello&quot;, &quot;world&quot;]    println!(&quot;转大写: &#123;&#125;&quot;, s.to_uppercase());         // 输出 HELLO WORLD    println!(&quot;去除空白: &#123;&#125;&quot;, &quot;  abc  &quot;.trim());       // 输出 abc&#125;
3. HashMap&lt;K, V&gt; 哈希映射
use std::collections::HashMap;fn main() &#123;    // 创建 HashMap    let mut scores = HashMap::new();    // 插入键值对    scores.insert(String::from(&quot;Blue&quot;), 10);    scores.insert(String::from(&quot;Yellow&quot;), 50);    // 访问值（get 返回 Option&lt;&amp;V&gt;）    let team = String::from(&quot;Blue&quot;);    match scores.get(&amp;team) &#123;        Some(score) =&gt; println!(&quot;Blue 队分数: &#123;&#125;&quot;, score),        None =&gt; println!(&quot;Blue 队不存在&quot;),    &#125;    // 遍历    for (key, value) in &amp;scores &#123;        println!(&quot;&#123;&#125;: &#123;&#125;&quot;, key, value);    &#125;    // 只在键不存在时插入    scores.entry(String::from(&quot;Blue&quot;)).or_insert(100);   // Blue 已存在，不更新    scores.entry(String::from(&quot;Red&quot;)).or_insert(30);     // Red 不存在，插入 30    println!(&quot;插入后: &#123;:?&#125;&quot;, scores);    // 基于旧值更新    let text = &quot;hello world hello&quot;;    let mut word_count = HashMap::new();    for word in text.split_whitespace() &#123;        let count = word_count.entry(word).or_insert(0);        *count += 1; // 解引用修改    &#125;    println!(&quot;词频统计: &#123;:?&#125;&quot;, word_count); // 输出 &#123;&quot;hello&quot;: 2, &quot;world&quot;: 1&#125;    // 从 Vec 创建 HashMap    let teams = vec![String::from(&quot;Blue&quot;), String::from(&quot;Yellow&quot;)];    let initial_scores = vec![10, 50];    let team_scores: HashMap&lt;_, _&gt; =        teams.into_iter().zip(initial_scores.into_iter()).collect();    println!(&quot;聚合结果: &#123;:?&#125;&quot;, team_scores);&#125;
模块系统和包管理
Rust 的模块系统由四个核心概念组成：包（Package）、Crate（库/二进制）、模块（Module）、路径（Path）。use 关键字用于将路径引入作用域。

1. 模块定义与可见性
// 定义模块树mod front_of_house &#123;    // 默认模块内容是私有的    pub mod hosting &#123;          // pub 使模块公开        pub fn add_to_waitlist() &#123;  // pub 使函数公开            println!(&quot;已添加到等候名单&quot;);        &#125;        fn seat_at_table() &#123;  // 私有函数，仅在模块内部可用            println!(&quot;请就座&quot;);        &#125;    &#125;    mod serving &#123;        fn take_order() &#123;            println!(&quot;点菜&quot;);            // super 引用父模块            super::hosting::add_to_waitlist();        &#125;    &#125;&#125;// 使用 pub use 重新导出（re-export）pub use front_of_house::hosting;// 使用 use 引入路径use front_of_house::hosting::add_to_waitlist;fn eat_at_restaurant() &#123;    // 绝对路径    crate::front_of_house::hosting::add_to_waitlist();    // 相对路径    front_of_house::hosting::add_to_waitlist();    // 使用 use 引入后可直接调用    add_to_waitlist();&#125;fn main() &#123;    eat_at_restaurant();&#125;
2. 多文件模块结构
// 在实际项目中，模块通常会拆分到不同文件中：//// src/main.rs// mod garden;  // 告诉编译器在 src/garden.rs 或 src/garden/mod.rs 中查找模块//// src/garden.rs （或 src/garden/mod.rs）// pub mod vegetables;  // 在 src/garden/vegetables.rs 中//// 旧式路径：src/garden/vegetables.rs// 新式路径：src/garden/vegetables/mod.rs// 以一个简化示例演示 mod 的机制：mod utils &#123;    pub fn greet(name: &amp;str) &#123;        println!(&quot;你好，&#123;&#125;！&quot;, name);    &#125;&#125;fn main() &#123;    utils::greet(&quot;Rustacean&quot;); // 输出 你好，Rustacean！&#125;
3. use 关键字用法
use std::collections::HashMap;use std::io::&#123;self, Write&#125;;              // 同时引入多个（io 自身也被引入）use std::collections::*;                 // glob 引入（谨慎使用）fn main() &#123;    let mut map = HashMap::new();        // 不用写 std::collections::HashMap    map.insert(&quot;key&quot;, &quot;value&quot;);    println!(&quot;&#123;:?&#125;&quot;, map);    // io::stdout() 和 Write trait    let mut stdout = io::stdout();    writeln!(stdout, &quot;通过 use 简化了路径！&quot;).unwrap();&#125;
4. Cargo 包管理
// Cargo.toml 文件示例（注释形式演示，不是可执行代码）：//// [package]// name = &quot;my_project&quot;// version = &quot;0.1.0&quot;// edition = &quot;2021&quot;  # Rust 版本//// [dependencies]// serde = &quot;1.0&quot;           # 添加依赖// rand = &#123; version = &quot;0.8&quot;, features = [&quot;small_rng&quot;] &#125;  # 指定版本和 features//// [dev-dependencies]// criterion = &quot;0.5&quot;       # 仅用于测试/基准测试的依赖//// 常用 Cargo 命令：// cargo new project_name      # 创建新项目// cargo build                 # 编译项目// cargo build --release       # 编译发布版本（优化）// cargo run                   # 编译并运行// cargo test                  # 运行测试// cargo check                 # 检查代码能否编译（比 build 快）// cargo doc --open            # 生成并打开文档// cargo update                # 更新依赖// cargo add &lt;crate&gt;           # 添加依赖（需安装 cargo-edit）fn main() &#123;    println!(&quot;Cargo 是 Rust 的构建系统和包管理器！&quot;);&#125;
错误处理
Rust 将错误分为两类：可恢复错误（Result&lt;T, E&gt;）和不可恢复错误（panic!）。推荐使用 Result 进行错误传播。

1. panic! 宏（不可恢复错误）
fn main() &#123;    // panic! 会立即终止程序并展开栈（unwinding）    // panic!(&quot;程序崩溃了！&quot;);  // 取消注释试试    // 直接设置环境变量可获取更详细的回溯：    // $env:RUST_BACKTRACE=1  (PowerShell)    // export RUST_BACKTRACE=1 (bash)    let v = vec![1, 2, 3];    // v[99]; // ❌ 索引越界，触发 panic    println!(&quot;v 有效: &#123;:?&#125;&quot;, v);&#125;
2. Result&lt;T, E&gt;（可恢复错误）
use std::fs::File;use std::io::&#123;self, Read, ErrorKind&#125;;fn main() &#123;    // 方式一：使用 match 处理 Result    let file_result = File::open(&quot;hello.txt&quot;);    let file = match file_result &#123;        Ok(f) =&gt; f,        Err(error) =&gt; match error.kind() &#123;            ErrorKind::NotFound =&gt; match File::create(&quot;hello.txt&quot;) &#123;                Ok(fc) =&gt; fc,                Err(e) =&gt; panic!(&quot;无法创建文件: &#123;:?&#125;&quot;, e),            &#125;,            other_error =&gt; panic!(&quot;打开文件出错: &#123;:?&#125;&quot;, other_error),        &#125;,    &#125;;    println!(&quot;文件打开成功: &#123;:?&#125;&quot;, file.metadata());    // 方式二：使用闭包和 unwrap_or_else（更简洁）    let _file2 = File::open(&quot;hello.txt&quot;).unwrap_or_else(|error| &#123;        if error.kind() == ErrorKind::NotFound &#123;            File::create(&quot;hello.txt&quot;).unwrap_or_else(|error| &#123;                panic!(&quot;无法创建文件: &#123;:?&#125;&quot;, error);            &#125;)        &#125; else &#123;            panic!(&quot;打开文件出错: &#123;:?&#125;&quot;, error);        &#125;    &#125;);&#125;// unwrap 和 expectfn demo_unwrap() &#123;    // unwrap：成功返回值，失败直接 panic    let _f = File::open(&quot;hello.txt&quot;).unwrap();    // expect：类似 unwrap，但可自定义 panic 消息（推荐用于原型开发）    let _f = File::open(&quot;hello.txt&quot;).expect(&quot;无法打开 hello.txt&quot;);&#125;
3. 错误传播（? 操作符）
use std::fs::&#123;self, File&#125;;use std::io::&#123;self, Read&#125;;// 传统方式：match 逐层传播错误fn read_username_from_file_v1() -&gt; Result&lt;String, io::Error&gt; &#123;    let f = File::open(&quot;username.txt&quot;);    let mut f = match f &#123;        Ok(file) =&gt; file,        Err(e) =&gt; return Err(e), // 遇到错误提前返回    &#125;;    let mut s = String::new();    match f.read_to_string(&amp;mut s) &#123;        Ok(_) =&gt; Ok(s),        Err(e) =&gt; Err(e),    &#125;&#125;// 使用 ? 操作符：遇到错误立即返回 Err（简洁！）fn read_username_from_file_v2() -&gt; Result&lt;String, io::Error&gt; &#123;    let mut f = File::open(&quot;username.txt&quot;)?; // ? = match + return Err    let mut s = String::new();    f.read_to_string(&amp;mut s)?;    Ok(s)&#125;// ? 可以链式调用，进一步简化fn read_username_from_file_v3() -&gt; Result&lt;String, io::Error&gt; &#123;    let mut s = String::new();    File::open(&quot;username.txt&quot;)?.read_to_string(&amp;mut s)?;    Ok(s)&#125;// 最简版本：使用标准库快捷函数fn read_username_from_file_v4() -&gt; Result&lt;String, io::Error&gt; &#123;    fs::read_to_string(&quot;username.txt&quot;) // std::fs::read_to_string 一步完成&#125;fn main() -&gt; Result&lt;(), Box&lt;dyn std::error::Error&gt;&gt; &#123;    // main 也可以返回 Result    match read_username_from_file_v4() &#123;        Ok(name) =&gt; println!(&quot;用户名: &#123;&#125;&quot;, name),        Err(e) =&gt; eprintln!(&quot;读取错误: &#123;&#125;&quot;, e),    &#125;    Ok(())&#125;
泛型（Generics）
泛型允许编写适用于多种类型的代码，减少重复。Rust 的泛型在编译时通过单态化（monomorphization）实现零成本抽象——为每个使用的具体类型生成专用代码。

1. 函数中的泛型
// 不使用泛型——需要为每种类型写一个函数fn largest_i32(list: &amp;[i32]) -&gt; &amp;i32 &#123;    let mut largest = &amp;list[0];    for item in list &#123;        if item &gt; largest &#123;            largest = item;        &#125;    &#125;    largest&#125;// 使用泛型（需要 PartialOrd trait bound，见下一章 Traits）fn largest&lt;T: PartialOrd&gt;(list: &amp;[T]) -&gt; &amp;T &#123;    let mut largest = &amp;list[0];    for item in list &#123;        if item &gt; largest &#123;            largest = item;        &#125;    &#125;    largest&#125;fn main() &#123;    let numbers = vec![34, 50, 25, 100, 65];    println!(&quot;最大数: &#123;&#125;&quot;, largest(&amp;numbers)); // 输出 100    let chars = vec![&#x27;y&#x27;, &#x27;m&#x27;, &#x27;a&#x27;, &#x27;q&#x27;];    println!(&quot;最大字符: &#123;&#125;&quot;, largest(&amp;chars)); // 输出 y&#125;
2. 结构体中的泛型
// 单泛型参数#[derive(Debug)]struct Point&lt;T&gt; &#123;    x: T,    y: T, // x 和 y 必须同类型&#125;// 多泛型参数#[derive(Debug)]struct Point2&lt;T, U&gt; &#123;    x: T,    y: U, // x 和 y 可以不同类型&#125;// 为泛型结构体实现方法impl&lt;T&gt; Point&lt;T&gt; &#123;    fn x(&amp;self) -&gt; &amp;T &#123;        &amp;self.x    &#125;&#125;// 只为特定类型实现方法impl Point&lt;f64&gt; &#123;    fn distance_from_origin(&amp;self) -&gt; f64 &#123;        (self.x.powi(2) + self.y.powi(2)).sqrt()    &#125;&#125;impl&lt;T: Clone, U&gt; Point2&lt;T, U&gt; &#123;    fn mixup&lt;V, W&gt;(self, other: Point2&lt;V, W&gt;) -&gt; Point2&lt;T, W&gt; &#123;        Point2 &#123;            x: self.x.clone(),            y: other.y,        &#125;    &#125;&#125;fn main() &#123;    let integer_point = Point &#123; x: 5, y: 10 &#125;;    let float_point = Point &#123; x: 1.0, y: 4.0 &#125;;    println!(&quot;int_point.x = &#123;&#125;&quot;, integer_point.x());    println!(&quot;float_point 到原点距离 = &#123;&#125;&quot;, float_point.distance_from_origin());    let p1 = Point2 &#123; x: 5, y: &quot;hello&quot; &#125;;    let p2 = Point2 &#123; x: &quot;world&quot;, y: &#x27;R&#x27; &#125;;    let p3 = p1.mixup(p2);    println!(&quot;mixup: &#123;:?&#125;&quot;, p3); // Point2 &#123; x: 5, y: &#x27;R&#x27; &#125;    // 不允许不同类型：Point &#123; x: 5, y: 4.0 &#125;; // ❌    // 需要不同类型用 Point2    let _flexible = Point2 &#123; x: 5, y: 4.0 &#125;;&#125;
3. 枚举中的泛型
// 标准库中的 Option 和 Result 就是泛型枚举// enum Option&lt;T&gt; &#123; Some(T), None &#125;// enum Result&lt;T, E&gt; &#123; Ok(T), Err(E) &#125;#[derive(Debug)]enum MyResult&lt;T, E&gt; &#123;    Success(T),    Failure(E),&#125;fn main() &#123;    let ok: MyResult&lt;i32, String&gt; = MyResult::Success(42);    let err: MyResult&lt;i32, String&gt; = MyResult::Failure(String::from(&quot;出错了&quot;));    println!(&quot;&#123;:?&#125;, &#123;:?&#125;&quot;, ok, err);    // 使用 Option 和 Result    let x: Option&lt;i32&gt; = Some(10);    let y: Result&lt;i32, &amp;str&gt; = Ok(20);    println!(&quot;&#123;:?&#125;, &#123;:?&#125;&quot;, x, y);&#125;
Trait 与 Trait Bound
Trait 定义了类型之间共享的行为，类似于其他语言中的接口（interface）。Trait Bound 用于约束泛型参数必须实现某些 trait。

1. 定义和实现 Trait
// 定义 traitpub trait Summary &#123;    // 方法签名（无默认实现）    fn summarize_author(&amp;self) -&gt; String;    // 带默认实现的方法    fn summarize(&amp;self) -&gt; String &#123;        // 默认实现可以调用同一 trait 中的其他方法        format!(&quot;(阅读更多来自 &#123;&#125; 的内容...)&quot;, self.summarize_author())    &#125;&#125;// 定义一个结构体pub struct Article &#123;    pub headline: String,    pub author: String,    pub content: String,&#125;pub struct Tweet &#123;    pub username: String,    pub content: String,    pub retweet: bool,&#125;// 为 Article 实现 Summaryimpl Summary for Article &#123;    fn summarize_author(&amp;self) -&gt; String &#123;        format!(&quot;@&#123;&#125;&quot;, self.author)    &#125;    // summarize 使用默认实现&#125;// 为 Tweet 实现 Summary（覆盖默认实现）impl Summary for Tweet &#123;    fn summarize_author(&amp;self) -&gt; String &#123;        format!(&quot;@&#123;&#125;&quot;, self.username)    &#125;    fn summarize(&amp;self) -&gt; String &#123;        format!(&quot;&#123;&#125;: &#123;&#125;&quot;, self.username, self.content)    &#125;&#125;fn main() &#123;    let article = Article &#123;        headline: String::from(&quot;Rust 很强大&quot;),        author: String::from(&quot;Ferris&quot;),        content: String::from(&quot;今天我们来学习 Rust...&quot;),    &#125;;    let tweet = Tweet &#123;        username: String::from(&quot;ferris_rustacean&quot;),        content: String::from(&quot;Rust is awesome!&quot;),        retweet: false,    &#125;;    println!(&quot;文章摘要: &#123;&#125;&quot;, article.summarize());    println!(&quot;推文摘要: &#123;&#125;&quot;, tweet.summarize());&#125;
2. Trait Bound（约束）
use std::fmt::&#123;Debug, Display&#125;;// 使用 trait bound 约束泛型参数pub fn notify(item: &amp;impl Summary) &#123;    // impl Summary 表示参数必须实现了 Summary trait    println!(&quot;快讯！&#123;&#125;&quot;, item.summarize());&#125;// 等价写法（trait bound 语法，更灵活）pub fn notify_bound&lt;T: Summary&gt;(item: &amp;T) &#123;    println!(&quot;快讯！&#123;&#125;&quot;, item.summarize());&#125;// 多个 trait boundpub fn notify_and_debug(item: &amp;(impl Summary + Display)) &#123;&#125;// 等价的 where 子句（约束多时推荐使用，可读性好）pub fn some_function&lt;T, U&gt;(t: &amp;T, u: &amp;U) -&gt; Stringwhere    T: Display + Clone,    U: Clone + Debug,&#123;    format!(&quot;t=&#123;&#125;, u=&#123;:?&#125;&quot;, t, u)&#125;// 返回实现了 trait 的类型pub fn returns_summarizable() -&gt; impl Summary &#123;    Tweet &#123;        username: String::from(&quot;ferris&quot;),        content: String::from(&quot;返回 impl Trait&quot;),        retweet: false,    &#125;    // 注意：只能返回一种具体类型，不能有条件地返回不同类型&#125;fn main() &#123;    let tweet = returns_summarizable();    println!(&quot;&#123;&#125;&quot;, tweet.summarize());    let s1 = String::from(&quot;hello&quot;);    let s2 = String::from(&quot;world&quot;);    println!(&quot;&#123;&#125;&quot;, some_function(&amp;s1, &amp;s2));&#125;
3. 派生 Trait（Derive）
// 通过 #[derive] 属性自动实现常用 trait#[derive(Debug, Clone, PartialEq, Eq, Hash)]  // Debug: 打印调试信息struct Person &#123;                                 // Clone: 显式克隆    name: String,                               // PartialEq/Eq: 相等比较    age: u32,                                   // Hash: 哈希&#125;fn main() &#123;    let p1 = Person &#123; name: String::from(&quot;Alice&quot;), age: 30 &#125;;    let p2 = p1.clone(); // Clone trait    println!(&quot;&#123;:?&#125;&quot;, p1);           // Debug trait    println!(&quot;p1 == p2: &#123;&#125;&quot;, p1 == p2); // PartialEq trait&#125;
4. Orphan Rule（孤儿规则）
// 孤儿规则：只能为当前 crate 中的类型实现外部 trait，// 或者为外部类型实现当前 crate 中的 trait。// 不能为外部类型实现外部 trait（避免冲突）。use std::fmt::Display;// 本地类型 + 外部 trait = ✅ 允许struct MyVec(Vec&lt;i32&gt;);impl Display for MyVec &#123;    fn fmt(&amp;self, f: &amp;mut std::fmt::Formatter&lt;&#x27;_&gt;) -&gt; std::fmt::Result &#123;        write!(f, &quot;MyVec with &#123;&#125; elements&quot;, self.0.len())    &#125;&#125;fn main() &#123;    let mv = MyVec(vec![1, 2, 3]);    println!(&quot;&#123;&#125;&quot;, mv);    // 但不能 impl Display for Vec&lt;i32&gt;  // ❌ 外部类型 + 外部 trait&#125;
生命周期（Lifetimes）
生命周期是 Rust 用来防止悬垂引用的机制。生命周期注解描述了引用之间存活时间的关系，大多数情况下编译器可自动推断，复杂场景需要手动标注。

1. 生命周期基础
fn main() &#123;    // 编译器通过生命周期分析防止悬垂引用    &#123;        let x = 5;        let r = &amp;x;          // r 的生命周期不能超过 x        println!(&quot;r: &#123;&#125;&quot;, r);    &#125;    // r 在此已失效，x 也已失效    // 下面的代码不能通过编译：    // let r;    // &#123;    //     let x = 5;    //     r = &amp;x;           // ❌ x 活得不够久    // &#125;    // println!(&quot;r: &#123;&#125;&quot;, r); // r 引用了已释放的 x&#125;
2. 函数签名中的生命周期注解
// 生命周期注解语法：&amp;&#x27;a T// &#x27;a 是一种命名约定，读作&quot;生命周期 a&quot;// 编译器的借用检查器无法自动推断此函数的生命周期// 需要手动标注输入和输出引用之间的关系fn longest&lt;&#x27;a&gt;(x: &amp;&#x27;a str, y: &amp;&#x27;a str) -&gt; &amp;&#x27;a str &#123;    // &#x27;a 表示：返回引用的生命周期等于 x 和 y 中较短的那个    if x.len() &gt; y.len() &#123;        x    &#125; else &#123;        y    &#125;&#125;fn main() &#123;    let string1 = String::from(&quot;long string is long&quot;);    &#123;        let string2 = String::from(&quot;xyz&quot;);        let result = longest(&amp;string1, &amp;string2);        println!(&quot;最长的字符串是: &#123;&#125;&quot;, result); // ✅ result 的生命周期与 string2 一致    &#125;    // string2 已释放，result 也随之失效    // 下面的代码不能通过编译：    // let result;    // let string1 = String::from(&quot;long&quot;);    // &#123;    //     let string2 = String::from(&quot;xyz&quot;);    //     result = longest(&amp;string1, &amp;string2); // ❌ result 比 string2 活得久    // &#125;    // println!(&quot;&#123;&#125;&quot;, result);&#125;
3. 结构体中的生命周期
// 当结构体持有引用时，需要标注生命周期#[derive(Debug)]struct Excerpt&lt;&#x27;a&gt; &#123;    // &#x27;a 表示 part 引用的数据必须比 Excerpt 实例活得久    part: &amp;&#x27;a str,&#125;impl&lt;&#x27;a&gt; Excerpt&lt;&#x27;a&gt; &#123;    // 方法中生命周期省略规则通常可以自动推导，但此处需要显式标注    fn level(&amp;self) -&gt; i32 &#123;        3    &#125;    fn announce_and_return_part(&amp;self, announcement: &amp;str) -&gt; &amp;str &#123;        println!(&quot;注意: &#123;&#125;&quot;, announcement);        self.part  // 根据省略规则，返回值生命周期与 &amp;self 一致    &#125;&#125;fn main() &#123;    let novel = String::from(&quot;从前有座山，山里有座庙...&quot;);    let first_sentence = novel.split(&#x27;。&#x27;).next().expect(&quot;找不到句号&quot;);    let excerpt = Excerpt &#123; part: first_sentence &#125;;    println!(&quot;摘录: &#123;:?&#125;&quot;, excerpt);    println!(&quot;返回: &#123;&#125;&quot;, excerpt.announce_and_return_part(&quot;请注意&quot;));&#125;
4. 生命周期省略规则
// 三条省略规则（编译器在能推断时会自动添加）：// 1. 每个是引用的参数都有各自的生命周期注解// 2. 如果只有一个输入生命周期参数，该生命周期赋给所有输出参数// 3. 如果方法有多个输入生命周期参数，但其中一个是 &amp;self 或 &amp;mut self，//    则 self 的生命周期赋给所有输出参数fn first_word(s: &amp;str) -&gt; &amp;str &#123;    // 编译器根据规则 1 和 规则 2 自动推断:    // fn first_word&lt;&#x27;a&gt;(s: &amp;&#x27;a str) -&gt; &amp;&#x27;a str    let bytes = s.as_bytes();    for (i, &amp;item) in bytes.iter().enumerate() &#123;        if item == b&#x27; &#x27; &#123;            return &amp;s[..i];        &#125;    &#125;    &amp;s[..]&#125;fn main() &#123;    let s = &quot;hello world&quot;;    println!(&quot;第一个单词: &#123;&#125;&quot;, first_word(s));&#125;
5. 静态生命周期
// &#x27;static 是特殊的生命周期，表示引用在整个程序运行期间都有效// 所有字符串字面量都是 &#x27;static 生命周期fn main() &#123;    let s: &amp;&#x27;static str = &quot;我是静态字符串，永远有效&quot;;    println!(&quot;&#123;&#125;&quot;, s);    // 常量引用的数据通常是 &#x27;static    let pi: &amp;&#x27;static f64 = &amp;3.14159;    // 实际上，上面的写法不工作，因为 3.14159 是临时值。正确的写法：    // 要么用 const，要么直接用字面量    println!(&quot;pi 近似值: &#123;&#125;&quot;, pi);&#125;
常用标准库函数与实用宏
Rust 标准库和内置宏提供了丰富的工具函数，掌握它们能大幅提升开发效率。

1. 常用 println! / format! 系列宏
fn main() &#123;    let name = &quot;Ferris&quot;;    let age = 5;    // 基本占位符    println!(&quot;你好，&#123;&#125;！&quot;, name);    // 多个占位符 + 位置参数    println!(&quot;&#123;0&#125; 今年 &#123;1&#125; 岁，&#123;0&#125; 喜欢 Rust！&quot;, name, age);    // 命名参数    println!(&quot;&#123;name&#125; 写了 &#123;count&#125; 行代码&quot;, name = &quot;Alice&quot;, count = 1000);    // 调试打印    let arr = vec![1, 2, 3];    println!(&quot;数组: &#123;:?&#125;&quot;, arr);   // Debug 格式    println!(&quot;美化: &#123;:#?&#125;&quot;, arr);  // 带缩进的 Debug 格式    // 数字格式化    let num = 255;    println!(&quot;十进制: &#123;&#125;, 十六进制: &#123;:x&#125;, 八进制: &#123;:o&#125;, 二进制: &#123;:b&#125;&quot;, num, num, num, num);    println!(&quot;前导零: &#123;:08&#125;&quot;, 42);     // 输出 00000042    println!(&quot;精度: &#123;:.3&#125;&quot;, 3.14159);  // 输出 3.142    // 不换行和错误输出    print!(&quot;不换行...&quot;);    eprintln!(&quot;这是错误输出！&quot;); // 输出到 stderr    // format! 返回 String 而非打印    let msg = format!(&quot;&#123;&#125; + &#123;&#125; = &#123;&#125;&quot;, 1, 2, 3);    println!(&quot;&#123;&#125;&quot;, msg);&#125;
2. 常用宏
fn main() &#123;    // vec! —— 创建 Vec    let v = vec![1, 2, 3, 4, 5];    println!(&quot;&#123;:?&#125;&quot;, v);    // assert! / assert_eq! / assert_ne! —— 断言    assert!(1 + 1 == 2, &quot;数学失效了！&quot;);    assert_eq!(2 + 2, 4);               // 相等断言    assert_ne!(2 + 2, 5);               // 不等断言    // dbg! —— 快速调试（打印表达式与值，返回所有权）    let x = dbg!(5 * 10); // 打印： [file:line] 5 * 10 = 50    // todo! —— 标记未完成的代码（会触发 panic，但不阻碍编译）    // let unfinished = todo!(&quot;等会儿再实现&quot;);    // unimplemented! —— 标记未实现    // let not_done = unimplemented!(&quot;这个功能还没做&quot;);    // unreachable! —— 标记在逻辑上不可达的代码    // unreachable!(&quot;这里按理说永远执行不到&quot;);    // panic! —— 主动触发 panic    // panic!(&quot;手动触发崩溃&quot;);    // matches! —— 匹配宏，返回 bool    let opt = Some(42);    if matches!(opt, Some(x) if x &gt; 0) &#123;        println!(&quot;大于零的值！&quot;);    &#125;    // include_str! —— 编译时嵌入文件内容为 &amp;str    // let content = include_str!(&quot;./data.txt&quot;);    // concat! —— 编译时拼接字符串字面量    const GREETING: &amp;str = concat!(&quot;Hello&quot;, &quot;, &quot;, &quot;World!&quot;);    println!(&quot;&#123;&#125;&quot;, GREETING);    // env! / option_env! —— 编译时获取环境变量    // const HOME: &amp;str = env!(&quot;HOME&quot;);  // 不存在则编译失败    // const CONFIG: Option&lt;&amp;str&gt; = option_env!(&quot;CONFIG_PATH&quot;); // 不存在为 None    println!(&quot;所有宏演示完成！&quot;);&#125;
3. 常用标准库函数
use std::cmp;fn main() &#123;    // === 字符串操作 ===    let s = &quot;hello world&quot;;    println!(&quot;是否包含: &#123;&#125;&quot;, s.contains(&quot;world&quot;));    println!(&quot;是否以...开头: &#123;&#125;&quot;, s.starts_with(&quot;he&quot;));    println!(&quot;是否以...结尾: &#123;&#125;&quot;, s.ends_with(&quot;ld&quot;));    println!(&quot;替换: &#123;&#125;&quot;, s.replace(&quot;world&quot;, &quot;Rust&quot;));    println!(&quot;查找位置: &#123;:?&#125;&quot;, s.find(&quot;o&quot;));  // Some(4)    let parts: Vec&lt;&amp;str&gt; = s.split_whitespace().collect();    println!(&quot;按空白分割: &#123;:?&#125;&quot;, parts);    // === 数字操作 ===    println!(&quot;绝对值: &#123;&#125;&quot;, (-5i32).abs());    println!(&quot;次方: &#123;&#125;&quot;, 2i32.pow(10));       // 1024    println!(&quot;最大值: &#123;&#125;&quot;, cmp::max(10, 20));    println!(&quot;最小值: &#123;&#125;&quot;, cmp::min(10, 20));    println!(&quot;范围限制: &#123;&#125;&quot;, 100i32.clamp(0, 50)); // 50    println!(&quot;是否为 2 的幂: &#123;&#125;&quot;, 64u32.is_power_of_two()); // true    // === 浮点数专属 ===    let f = 3.14159_f64;    println!(&quot;四舍五入: &#123;&#125;&quot;, f.round());      // 3    println!(&quot;向上取整: &#123;&#125;&quot;, f.ceil());       // 4    println!(&quot;向下取整: &#123;&#125;&quot;, f.floor());      // 3    println!(&quot;截断: &#123;&#125;&quot;, f.trunc());          // 3    println!(&quot;平方根: &#123;&#125;&quot;, f.sqrt());    // === Option / Result 操作 ===    let opt_val = Some(3);    println!(&quot;unwrap_or: &#123;&#125;&quot;, opt_val.unwrap_or(0));    // 3    println!(&quot;map: &#123;:?&#125;&quot;, opt_val.map(|x| x * 2));      // Some(6)    println!(&quot;and_then: &#123;:?&#125;&quot;, opt_val.and_then(|x| Some(x + 1)));  // Some(4)    let filtered = opt_val.filter(|&amp;x| x &gt; 5);          // None    println!(&quot;filter: &#123;:?&#125;&quot;, filtered);    let result: Result&lt;i32, &amp;str&gt; = Ok(42);    println!(&quot;Result unwrap_or: &#123;&#125;&quot;, result.unwrap_or(0));    println!(&quot;Result map: &#123;:?&#125;&quot;, result.map(|x| x * 2));    // === 迭代器 ===    let numbers = vec![1, 2, 3, 4, 5];    let sum: i32 = numbers.iter().sum(); // 15    let doubled: Vec&lt;i32&gt; = numbers.iter().map(|x| x * 2).collect();    let evens: Vec&lt;&amp;i32&gt; = numbers.iter().filter(|&amp;&amp;x| x % 2 == 0).collect();    let found = numbers.iter().find(|&amp;&amp;x| x &gt; 3); // Some(&amp;4)    println!(&quot;sum: &#123;&#125;, doubled: &#123;:?&#125;, evens: &#123;:?&#125;, found: &#123;:?&#125;&quot;, sum, doubled, evens, found);    // === 类型转换 ===    let num_str = &quot;42&quot;.parse::&lt;i32&gt;().unwrap();   // 字符串转数字    println!(&quot;解析后的数字: &#123;&#125;&quot;, num_str);    let num_to_str = 42.to_string();               // 数字转字符串    println!(&quot;转换的字符串: &#123;&#125;&quot;, num_to_str);    let small: u8 = 10;    let big: u32 = small as u32;                   // 数值类型转换    println!(&quot;small as u32: &#123;&#125;&quot;, big);&#125;
4. 文件读写
use std::fs;use std::io::&#123;self, Write, BufRead, BufReader&#125;;use std::path::Path;fn main() -&gt; io::Result&lt;()&gt; &#123;    // 写入文件    fs::write(&quot;output.txt&quot;, &quot;Hello, Rust!\n第二行内容&quot;)?;    // 追加写入    let mut file = fs::OpenOptions::new()        .append(true)        .open(&quot;output.txt&quot;)?;    writeln!(file, &quot;追加的一行&quot;)?;    // 读取整个文件为 String    let content = fs::read_to_string(&quot;output.txt&quot;)?;    println!(&quot;文件内容:\n&#123;&#125;&quot;, content);    // 逐行读取    let file = fs::File::open(&quot;output.txt&quot;)?;    let reader = BufReader::new(file);    for (i, line) in reader.lines().enumerate() &#123;        println!(&quot;第 &#123;&#125; 行: &#123;&#125;&quot;, i + 1, line?);    &#125;    // 检查路径    let path = Path::new(&quot;output.txt&quot;);    println!(&quot;文件存在: &#123;&#125;&quot;, path.exists());    println!(&quot;是文件: &#123;&#125;&quot;, path.is_file());    // 读取目录    if Path::new(&quot;.&quot;).is_dir() &#123;        for entry in fs::read_dir(&quot;.&quot;)? &#123;            let entry = entry?;            println!(&quot;目录项: &#123;:?&#125;&quot;, entry.path());        &#125;    &#125;    Ok(())&#125;
Rust 中的异步编程（async/await）
Rust 的异步编程基于 Future trait 和 async/await 语法。异步代码不会阻塞线程，而是让出控制权等待 I/O 完成。运行时（如 tokio）负责调度执行。

1. 异步基础概念
// 异步编程核心概念// - async fn：定义一个返回 Future 的异步函数// - .await：等待一个 Future 完成，在此期间让出线程// - 运行时（Runtime）：如 tokio、async-std，负责调度和执行 Future// 注意：以下代码需要 tokio 运行时才能运行// 在 Cargo.toml 中添加：// [dependencies]// tokio = &#123; version = &quot;1&quot;, features = [&quot;full&quot;] &#125;
2. 基本 async/await 使用
// 使用 tokio 运行时（注释形式演示关键概念）// async 函数返回 impl Future&lt;Output = T&gt;async fn say_hello() -&gt; String &#123;    String::from(&quot;Hello from async!&quot;)&#125;async fn fetch_data(id: u32) -&gt; String &#123;    // 模拟异步 I/O 操作    // tokio::time::sleep 不会阻塞线程    // tokio::time::sleep(std::time::Duration::from_millis(100)).await;    format!(&quot;数据-&#123;&#125;&quot;, id)&#125;// 顺序执行async fn sequential() &#123;    let a = fetch_data(1).await;    let b = fetch_data(2).await;    println!(&quot;顺序: a=&#123;&#125;, b=&#123;&#125;&quot;, a, b); // 总耗时 ~200ms&#125;// 并发执行（通过 join! 宏同时等待多个 Future）async fn concurrent() &#123;    let (a, b) = tokio::join!(        fetch_data(1),        fetch_data(2),    );    println!(&quot;并发: a=&#123;&#125;, b=&#123;&#125;&quot;, a, b); // 总耗时 ~100ms&#125;// #[tokio::main] 将 main 函数转为异步运行时入口// #[tokio::main]// async fn main() &#123;//     say_hello().await;//     sequential().await;//     concurrent().await;// &#125;// 为了不使用外部依赖也能演示语法，这里写一个概念性的 main：fn main() &#123;    println!(&quot;=== Rust 异步编程概念 ===&quot;);    println!(&quot;&quot;);    println!(&quot;核心概念：&quot;);    println!(&quot;1. async fn 返回一个 Future&quot;);    println!(&quot;2. .await 等待 Future 完成，线程不会被阻塞&quot;);    println!(&quot;3. tokio::spawn 可在后台并发执行任务&quot;);    println!(&quot;4. tokio::join! 同时等待多个 Future&quot;);    println!(&quot;5. tokio::select! 竞速等待，哪个先完成处理哪个&quot;);    println!(&quot;&quot;);    println!(&quot;实际使用时需添加依赖到 Cargo.toml:&quot;);    println!(&quot;  tokio = &#123;&#123; version = \&quot;1\&quot;, features = [\&quot;full\&quot;] &#125;&#125;&quot;);&#125;
3. 并发任务处理模式
